(() => {
'use strict';
const D=window.STUDY_DATA,M=window.StudyModel,C=window.StudyCloud,$=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={plane:'<path d="m3 12 18-8-6 18-4-7-8-3Z"/><path d="m11 15 10-11"/>',home:'<path d="m3 10 9-7 9 7v10H15v-7H9v7H3Z"/>',book:'<path d="M12 5v16M3 4c4-1 7 0 9 2 2-2 5-3 9-2v15c-4-1-7 0-9 2-2-2-5-3-9-2Z"/>',test:'<rect x="5" y="4" width="14" height="18" rx="2"/><path d="M9 2h6v4H9zM8 11h8M8 15h8M8 19h4"/>',review:'<path d="M3 11a9 9 0 1 1 2 7M3 5v6h6M12 7v5l3 2"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',back:'<path d="m14 5-7 7 7 7"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',check:'<path d="m5 12 4 4L19 6"/>',star:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2L12 17.3l-5.6 2.9 1.1-6.2L3 9.6l6.2-.9Z"/>',layers:'<path d="m12 3 10 5-10 5L2 8l10-5ZM2 12l10 5 10-5M2 16l10 5 10-5"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',upload:'<path d="M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5"/>',note:'<path d="M14 3H5v18h14V8l-5-5Zm0 0v5h5M8 12h8M8 16h5"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',flag:'<path d="M5 21V3c5-4 9 4 14 0v10c-5 4-9-4-14 0"/>',cloud:'<path d="M7 18a5 5 0 1 1 0-10 6 6 0 0 1 11 0 5 5 0 0 1 0 10M12 11v10m-3-3 3 3 3-3"/>',device:'<rect x="6" y="2" width="12" height="20" rx="3"/><path d="M11 18h2"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${paths[n]||paths.book}</svg>`;
const prettyTime=t=>t?new Date(t).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}):'尚未同步';
const letter=n=>String.fromCharCode(65+n),tag=(s,c='')=>`<span class="tag ${c}">${esc(s)}</span>`;
let S,rawRecovery=null,storageOK=true,saveBlocked=false,toastTimer,pending=null,selectedSessionId=null,syncController=null;
let view={page:'home',chapter:null,libraryTab:'chapters',groupFilter:'all',search:'',type:'all',limit:40,testTab:'coverage',reviewTab:'wrong',roundDetails:false};
try{const raw=localStorage.getItem(M.KEY),old=localStorage.getItem(M.OLD_KEY);rawRecovery=raw||old;const data=JSON.parse(raw||old||'null');if(data)M.validateState(data,D.banks);S=M.migrate(data,D.banks);}catch(e){S=M.migrate(null,D.banks);storageOK=false;saveBlocked=true;}
let banks=[],qmap;
function rebuild(){banks=[...D.banks,...S.customBanks];qmap=M.questionMap(banks);M.ensurePlans(S,banks);}
rebuild();
const bank=()=>banks.find(b=>b.id===S.bank)||banks[0];
const questions=()=>bank().questions.map(q=>qmap.get(q.id));
const eligible=()=>questions().filter(q=>!q.excluded);
const groups=()=>S.plans[S.bank]?.groups||[];
const group=id=>groups().find(g=>g.id===id);
const chapter=n=>D.chapters.find(c=>c.number===+n)||{number:n,title:'第'+n+'章',short:'自定义章节',sections:[]};
const current=()=>S.sessions[selectedSessionId];
const currentQ=()=>{const s=current();return s&&qmap.get(s.ids[s.index]);};
const coverage=()=>M.currentRound(S,S.bank);
const record=id=>S.records[id]||{attempts:0,right:0,wrong:0,activeWrong:false,due:0};
function storedWarning(){const el=$('#storage-warning');el.hidden=storageOK&&!saveBlocked;if(!el.hidden)el.innerHTML=saveBlocked?'原有记录暂不能读取，已保留原数据。<button data-action="recover-raw">导出原数据</button>后可恢复备份。':'当前浏览器无法保存更多数据。请到“我的”导出学习备份，避免丢失本次进度。';}
function save(){if(saveBlocked){storedWarning();return false;}try{localStorage.setItem(M.KEY,JSON.stringify(M.snapshot(S)));storageOK=true;}catch{storageOK=false;}storedWarning();return storageOK;}
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function go(page){view.page=page;history.replaceState(null,'','#'+page);render();window.scrollTo(0,0);}
function sheet(title,body){$('#sheet-content').innerHTML=`<div class="sheet-head"><h2>${esc(title)}</h2><button class="icon-btn" data-action="close" aria-label="关闭">${icon('close')}</button></div><div class="sheet-body">${body}</div>`;if(!$('#sheet').open)$('#sheet').showModal();}
function close(){if(syncController)syncController.abort();$('#sheet').close();}
function download(name,data,type='application/json'){const blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);}
const button=(label,action,value='',css='')=>`<button class="btn ${css}" data-action="${action}" data-value="${esc(value)}">${label}</button>`;
const textButton=(label,action,value='')=>`<button class="text-btn" data-action="${action}" data-value="${esc(value)}">${label}</button>`;
const heading=(title,subtitle)=>`<div class="page-heading"><h1>${title}</h1><p class="muted">${subtitle}</p></div>`;
const section=(title,extra='')=>`<div class="section-title"><h2>${title}</h2>${extra}</div>`;
const bar=(value,total)=>`<div class="bar"><span style="width:${total?Math.min(100,value/total*100):0}%"></span></div>`;
const empty=(title,text,action='groups',label='选择章节')=>`<div class="empty"><div class="empty-icon">${icon('book')}</div><h3>${title}</h3><p>${text}</p>${action?button(label,'nav',action,'light'):''}</div>`;
function top(){return `<header class="container app-header"><div class="brand"><span class="brand-symbol">${icon('plane')}</span>低空研习<small>2.0</small></div><button class="bank-switch" data-action="banks" aria-label="切换题库">${icon('layers')}<span>${esc(bank().shortName||bank().name)}</span>${icon('down')}</button></header>`;}
function nav(){return `<nav class="bottom-nav" aria-label="主导航"><div class="nav-inner">${[['home','home','首页'],['groups','book','学习'],['tests','test','自测'],['review','review','复习'],['me','user','我的']].map(([p,i,n])=>`<button class="nav-item ${view.page===p?'active':''}" data-action="nav" data-value="${p}" ${view.page===p?'aria-current="page"':''}>${icon(i)}<span>${n}</span>${p==='review'&&eligible().some(q=>record(q.id).activeWrong)?'<i class="nav-dot"></i>':''}</button>`).join('')}</div></nav>`;}
function syncStatus(){if(!S.sync.lastSuccessAt)return'已保存到本机';return S.updatedAt>S.sync.lastSyncedAt?'本机有更新，待手动同步':'上次手动同步 '+prettyTime(S.sync.lastSuccessAt);}
function syncLine(){return `<div class="save-line"><span>${icon('device')}${esc(syncStatus())}</span>${textButton(icon('cloud')+'手动云同步','sync-open')}</div>`;}
function excludedNote(){const n=bank().questions.filter(q=>q.excluded).length;return n?`<div class="callout warning mt16">${icon('info')}<span>此题库有 ${n} 道暂缓使用题，学习与自测按 ${eligible().length} 道可用题统计。${textButton('查看原因','excluded')}</span></div>`:'';}
function recommendation(){
 const last=S.sessions[S.lastActivity[S.bank]?.sessionId];
 if(last&&last.kind==='study'&&!last.ids.every(id=>S.reading[id]))return{label:'继续学习',title:last.title,detail:'上次停在第 '+(last.index+1)+' 题',action:'session-open',value:last.id};
 if(last&&last.kind!=='study'&&M.sessionSummary(last).blank>0)return{label:last.submissions?.length?'补答未答题':'继续自测',title:last.title,detail:'已保存答案，随时接着做',action:'session-open',value:last.id};
 const waiting=groups().find(g=>{const x=M.groupStats(S,g);return x.readComplete&&!x.testComplete;});
 if(waiting)return{label:'测这一组',title:'第'+waiting.chapter+'章 · 第'+waiting.number+'组',detail:'已经看完，用自测检查理解',action:'group-test',value:waiting.id};
 const unread=groups().find(g=>!g.ids.every(id=>S.reading[id]));
 if(unread)return{label:'开始学习',title:'第'+unread.chapter+'章 · 第'+unread.number+'组',detail:chapter(unread.chapter).short+' · '+unread.ids.length+'题',action:'study-group',value:unread.id};
 const r=coverage(),paper=r?.papers.find(p=>M.sessionSummary(S.sessions[p.sessionId]||{ids:p.ids,responses:{}}).blank);
 if(paper)return{label:'继续这一卷',title:'第'+r.number+'轮 · 第'+paper.number+'卷',detail:paper.ids.length+'题 · 不限时，可续答',action:'paper-open',value:paper.id};
 return{label:'进入自测计划',title:'看过的知识，再检验一次',detail:'组内自测和整库覆盖分别记录',action:'nav',value:'tests'};
}
function home(){
 const t=M.bankStats(S,bank()),next=recommendation(),todayRead=Object.values(S.reading).filter(d=>d===M.day()).length;
 return `${S.migration&&!S.migration.noticeSeen?`<div class="migration-banner"><div><strong>旧版进度已保留</strong><p>已看、错题、笔记、收藏和旧成绩均已迁移。旧随机自测不会算作新轮覆盖。</p></div>${textButton('知道了','migration-seen')}</div>`:''}<div class="home-intro"><span class="eyebrow">学习计划 · ${esc(bank().shortName||bank().name)}</span><h1>今天，接着学。</h1><p class="muted small">看过多少、测过多少，都清楚记在这里。</p></div><section class="progress-panel" aria-label="当前题库学习进度"><div class="row between"><span class="small">累计已看</span><span class="tiny muted">重复查看不重复计数</span></div><div class="reading-total"><b>${t.read}</b><span>/ ${t.total} 题</span><strong>${Math.round(t.read/t.total*100)||0}%</strong></div>${bar(t.read,t.total)}<div class="progress-metrics"><div><span>组内自测覆盖</span><b>${t.groupTested}<small> / ${t.total}</small></b></div><div><span>整库本轮覆盖</span><b>${t.round.covered}<small> / ${t.round.total||t.total}</small></b></div><div><span>今日新看</span><b>${todayRead}<small> / 目标 ${S.settings.goal}</small></b></div></div><p class="milestone">已看完 ${t.readGroups}/${t.groupCount} 组 · 尚未看 ${t.total-t.read} 题</p></section>${syncLine()}<section class="continue-panel"><div class="row between"><span class="tag">接着上一步</span>${textButton('选其他组','nav','groups')}</div><h2>${esc(next.title)}</h2><p>${esc(next.detail)}</p>${button(esc(next.label)+icon('arrow'),next.action,next.value,'full')}</section><div class="section-split">${section('整库自测计划',textButton('查看各卷'+icon('chevron'),'nav','tests'))}<div class="plan-preview"><div class="row between"><div><h3>${coverage()?'第'+coverage().number+'轮':'准备开始第1轮'}</h3><p>${coverage()?t.round.completedPapers+'/'+t.round.paperCount+'卷完成':'每卷50题，整轮无重复、无漏题'}</p></div><span class="plan-count">${Math.ceil(t.total/50)}<small> 卷</small></span></div>${bar(t.round.covered,t.total)}<p class="tiny muted mt8">${coverage()?'本轮还剩 '+t.round.remaining+' 题未覆盖':'按章节和单多选比例分配；未答不计覆盖。'}</p></div></div>${section('按章节，走完知识地图',textButton('全部章节'+icon('chevron'),'nav','groups'))}${chapterRows(4)}${section('把薄弱处再看一次')}<div class="review-entry"><div>${icon('review')}<span><strong>${t.wrong} 道待巩固错题</strong><small>错题复习独立记录，不增加整库覆盖。</small></span></div>${textButton('去复习'+icon('chevron'),'nav','review')}</div>${excludedNote()}`;
}
const focusGroups=[{name:'需求到验收',detail:'变更 · 风险 · 交付',chapters:[4],tag:'流程判断'},{name:'四平台协同',detail:'定位 · 选型 · 分工',chapters:[5,7],tag:'易混边界'},{name:'通导监能力',detail:'覆盖 · 定位 · 感知',chapters:[6,16],tag:'技术选型'},{name:'行业方案闭环',detail:'应急 · 政务 · 物流',chapters:[8,9,10,11,12],tag:'场景应用'},{name:'部署与排障',detail:'平台 · 中间件 · 安全',chapters:[14,15,20],tag:'排障顺序'},{name:'作业与终端',detail:'航线 · 计划 · 天枢',chapters:[17,18],tag:'实操决策'}];
function focusCards(){if(!D.banks.some(b=>b.id===S.bank))return '';return section('重点题型，单独巩固')+`<p class="small muted mb16">按课程重点整理；每次最多20题，不计整库覆盖。</p><div class="focus-grid">${focusGroups.map((f,i)=>`<button class="focus-card" data-action="focus-start" data-value="${i}">${tag(f.tag,i%2?'orange':'blue')}<h3>${f.name}</h3><p>${f.detail}</p><div class="row">开始专项${icon('arrow')}</div></button>`).join('')}</div>`;}
function chapterRows(limit=Infinity){
 const nums=[...new Set(groups().map(g=>g.chapter))];return `<div class="chapter-list">${nums.slice(0,limit).map(n=>{const gs=groups().filter(g=>g.chapter===n),ids=gs.flatMap(g=>g.ids),read=ids.filter(id=>S.reading[id]).length;return `<button class="chapter-row" data-action="chapter-open" data-value="${n}"><span class="chapter-num">${String(n).padStart(2,'0')}</span><div class="grow"><h3>${esc(chapter(n).short)}</h3><p>${gs.length}组 · ${ids.length}题</p></div><div class="chapter-meta"><b>已看 ${read}/${ids.length}</b>${bar(read,ids.length)}</div>${icon('chevron')}</button>`;}).join('')}</div>`;
}
function groupCard(g){
 const x=M.groupStats(S,g);let label=x.testComplete?'已自测':x.readComplete?'看完未测':x.read?'学习中':'未开始';
 const session=S.sessions['study:'+g.id],detail=x.summary&&x.latest.submissions?.length?`最近自测 ${x.summary.score}% · ${x.summary.blank?'待补'+x.summary.blank+'题':'已答完'}`:session?'上次第 '+(session.index+1)+' 题':'可随时选择这一组';
 return `<article class="group-card"><div class="row between"><h3>第 ${g.number} 组 <span class="small muted">· ${g.ids.length}题</span></h3>${tag(label,x.testComplete?'':x.readComplete?'blue':'neutral')}</div><p class="group-counts">已看 <b>${x.read}/${x.total}</b><span>组内已测 <b>${x.tested}/${x.total}</b></span></p>${bar(x.read,x.total)}<div class="row between tiny muted mt8"><span>${esc(detail)}</span>${x.wrong?tag('错题 '+x.wrong,'orange'):''}</div><div class="group-actions">${button((x.read?'继续学习':'看题学习')+icon('book'),'study-group',g.id,'light')}${button(x.latest&&x.summary.blank?'继续自测':x.testComplete?'查看自测':'测这一组','group-test',g.id,'outline')}</div></article>`;
}
function library(){
 if(view.libraryTab==='questions')return `${heading('查找题目',esc(bank().name))}<div class="top-action-row">${textButton(icon('back')+'章节目录','library-chapters')}${view.type==='uncovered'?textButton('回整库计划','nav','tests'):''}</div><div class="search">${icon('search')}<input id="search" type="search" value="${esc(view.search)}" placeholder="搜索题干、考点、题号或选项" aria-label="搜索题目" autocomplete="off"></div><div class="filter-pills">${[['all','全部'],['single','单选'],['multi','多选'],['unseen','未看'],['seen','已看'],['uncovered','本轮未覆盖']].map(([v,n])=>`<button class="${view.type===v?'active':''}" data-action="search-type" data-value="${v}">${n}</button>`).join('')}</div><div id="question-results">${searchResults()}</div>`;
 if(view.chapter===null)return `${heading('章节学习',`每组约15题，固定分组。已看 ${M.bankStats(S,bank()).read}/${eligible().length} 题。`)}<div class="top-action-row"><span class="small muted">${groups().length} 个学习小组</span>${textButton(icon('search')+'查找题目','library-search')}</div>${chapterRows()}${focusCards()}${excludedNote()}`;
 const gs=groups().filter(g=>g.chapter===+view.chapter),ids=gs.flatMap(g=>g.ids),read=ids.filter(id=>S.reading[id]).length;
 const filters={all:()=>true,unseen:g=>!M.groupStats(S,g).read,reading:g=>{const x=M.groupStats(S,g);return x.read>0&&!x.readComplete;},untested:g=>{const x=M.groupStats(S,g);return x.readComplete&&!x.testComplete;},wrong:g=>M.groupStats(S,g).wrong>0};
 const filtered=gs.filter(filters[view.groupFilter]||filters.all);
 return `<div class="top-action-row">${textButton(icon('back')+'全部章节','chapter-back')}${textButton('本章学习要点','chapter-source',view.chapter)}</div>${heading('第 '+view.chapter+' 章',esc(chapter(view.chapter).short))}<div class="chapter-summary"><strong>已看 ${read}/${ids.length} 题</strong><span>${gs.length} 个固定小组</span>${bar(read,ids.length)}</div><div class="filter-pills">${[['all','全部'],['unseen','未开始'],['reading','学习中'],['untested','看完未测'],['wrong','有错题']].map(([v,n])=>`<button class="${view.groupFilter===v?'active':''}" data-action="group-filter" data-value="${v}">${n}</button>`).join('')}</div><div class="group-grid">${filtered.length?filtered.map(groupCard).join(''):empty('当前没有这类小组','可以切换筛选条件查看其他组。',null)}</div><p class="footer-note">分组在本章内均衡分配。学习、自测与断点分别保存；切换小组不会覆盖其他组。</p>`;
}
function coveredIds(round=coverage()){const out=new Set();if(round)for(const p of round.papers)for(const id of p.ids)if(S.sessions[p.sessionId]?.responses[id])out.add(id);return out;}
function paperFor(qid){return coverage()?.papers.find(p=>p.ids.includes(qid));}
function filteredQuestions(){
 const query=view.search.trim().toLowerCase(),covered=coveredIds();return questions().filter(q=>{
  const type=view.type==='all'||view.type===q.type||view.type==='unseen'&&!S.reading[q.id]||view.type==='seen'&&S.reading[q.id]||view.type==='uncovered'&&!q.excluded&&!covered.has(q.id);
  return type&&(!query||[q.stem,q.focus,q.displayId,q.id,...q.options].join(' ').toLowerCase().includes(query));
 });
}
function questionCard(q){const r=record(q.id),p=paperFor(q.id);return `<button class="question-item" data-action="peek" data-value="${esc(q.id)}"><div class="row">${tag(q.type==='multi'?'多选':'单选',q.type==='multi'?'blue':'')}<span class="meta">${esc(q.displayId||q.id)} · 第${q.chapter}章</span><span class="status">${q.excluded?'暂缓使用':r.activeWrong?'待巩固':S.reading[q.id]?'已看':'未看'}</span></div><p>${esc(q.stem)}</p><span class="meta">${esc(q.focus||chapter(q.chapter).short)}${view.type==='uncovered'&&p?' · 第'+coverage().number+'轮第'+p.number+'卷':''}${r.wrong?' · 错'+r.wrong+'次':''}</span></button>`;}
function searchResults(){const qs=filteredQuestions();return `<p class="count-label mb16">找到 ${qs.length} 题${view.type==='uncovered'?' · 交卷后才计覆盖':''}</p><div class="question-list">${qs.slice(0,view.limit).map(questionCard).join('')}</div>${!qs.length?empty('没有匹配题目','换个关键词或筛选条件。',null):qs.length>view.limit?button('继续加载','load-more','','outline full mt16'):''}`;}
function testTabs(){return `<div class="segmented" role="group" aria-label="自测类型">${[['group','组内自测'],['coverage','整库覆盖自测']].map(([v,n])=>`<button class="${view.testTab===v?'active':''}" data-action="test-tab" data-value="${v}">${n}</button>`).join('')}</div>`;}
function tests(){
 if(view.testTab==='group'){
  const list=groups().filter(g=>M.groupStats(S,g).read||M.groupStats(S,g).tested),t=M.bankStats(S,bank());
  return `${heading('学过一组，测清一组','范围是同一个学习组，成绩与整库覆盖分别记录。')}${testTabs()}<div class="test-progress-summary"><span>组内自测覆盖</span><b>${t.groupTested}<small> / ${t.total}题</small></b>${bar(t.groupTested,t.total)}</div><div class="top-action-row"><span class="small muted">${list.length} 个已开始的小组</span>${textButton('选择其他组','nav','groups')}</div><div class="group-grid">${list.length?list.map(g=>{const x=M.groupStats(S,g);return `<article class="group-card"><div class="row between"><h3>第${g.chapter}章 · 第${g.number}组</h3>${tag(x.testComplete?'已测完':x.tested?'待补答':'未自测',x.testComplete?'':'neutral')}</div><p class="small muted mt8">${esc(chapter(g.chapter).short)}</p><p class="group-counts">已看 ${x.read}/${x.total}<span>已测 ${x.tested}/${x.total}</span></p>${x.summary&&x.latest.submissions?.length?`<p class="small">最近 ${x.summary.score}% · 错 ${x.summary.wrong} · 未答 ${x.summary.blank}</p>`:''}<div class="group-actions">${button(x.latest?'打开这次自测':'测这一组','group-test',g.id,'light')}${x.latest?.submissions?.length?button('再测一次','group-retest',g.id,'outline'):button('回看学习','study-group',g.id,'outline')}</div></article>`;}).join(''):empty('先选一组开始学习','学过的小组会出现在这里，也可以从章节目录直接选组自测。')}</div>`;
 }
 const r=coverage(),n=eligible().length;
 if(!r)return `${heading('测遍整库，心里有数','整轮先分好题，各卷之间不重复。')}${testTabs()}<article class="round-start"><span class="tag">第1轮 · 待开始</span><h2>${n} 题，${Math.ceil(n/50)} 卷</h2><p>每卷50题，末卷按实际余题。<br>不限时，可中断续答。</p><div class="round-rules"><span>${icon('check')}同轮各卷不重复</span><span>${icon('check')}未答不计覆盖</span><span>${icon('check')}新轮保留旧成绩</span></div>${button('创建第1轮自测计划'+icon('arrow'),'round-new','','full')}</article>${excludedNote()}<p class="footer-note">整库自测与组内自测、错题复习独立。这里的卷数和规则是学习计划，不代表官方考试安排。</p>`;
 const t=M.roundStats(S,r),list=S.rounds[S.bank]||[];
 return `${heading('整库覆盖自测','每一轮都有完整题单，换一卷不会重新随机抽题。')}${testTabs()}<div class="round-toolbar"><select id="round-picker" class="select" aria-label="查看自测轮次">${list.map(x=>`<option value="${esc(x.id)}" ${x.id===r.id?'selected':''}>第${x.number}轮 · 覆盖${M.roundStats(S,x).covered}/${x.ids.length}</option>`).join('')}</select>${textButton(icon('layers')+'开启新一轮','round-new')}</div><section class="round-progress"><div class="row between"><span>第 ${r.number} 轮 · 已覆盖</span>${tag(t.covered===t.total?'本轮已完成':'进行中',t.covered===t.total?'':'blue')}</div><div class="reading-total"><b>${t.covered}</b><span>/ ${t.total} 题</span><strong>${Math.round(t.covered/t.total*100)}%</strong></div>${bar(t.covered,t.total)}<div class="row between tiny muted mt16"><span>${t.completedPapers}/${t.paperCount} 卷答完 · 还剩 ${t.remaining} 题</span>${textButton('查看未覆盖题','uncovered')}</div></section><div class="paper-grid">${r.papers.map(p=>{const s=S.sessions[p.sessionId],x=s?M.sessionSummary(s):{answered:0,blank:p.ids.length,score:0},drafts=s?Object.entries(s.drafts).filter(([id,d])=>d.selected?.length&&!s.responses[id]).length:0,label=!s?'未开始':!x.blank?'已完成':x.answered?'待补答':'作答中';return `<article class="paper-card"><div class="row between"><h3>第 ${String(p.number).padStart(2,'0')} 卷</h3>${tag(label,!x.blank?'':'neutral')}</div><p class="small muted">${p.ids.length}题 · ${p.ids.filter(id=>qmap.get(id)?.type==='single').length}单选 / ${p.ids.filter(id=>qmap.get(id)?.type==='multi').length}多选</p><div class="paper-progress"><strong>${x.answered}<small> / ${p.ids.length}</small></strong><span>已提交</span></div>${bar(x.answered,p.ids.length)}<p class="tiny muted mt8">${!x.blank?'成绩 '+x.score+'%':drafts?'另有 '+drafts+' 题草稿已保存':x.answered?'未答 '+x.blank+' 题待补测':'本卷题目已经固定'}</p>${button(!s?'开始这卷':!x.blank?'查看结果':x.answered?'补答未答题':'继续这卷','paper-open',p.id,!x.blank?'outline full':'light full')}</article>`;}).join('')}</div><div class="callout mt16">${icon('info')}<span>错题算已测，同时进入复习；未答不算已测。开启新轮只新建计划，不清除任何旧轮、错题或学习记录。</span></div>${excludedNote()}`;
}
function review(){const wrong=eligible().filter(q=>record(q.id).activeWrong),due=eligible().filter(q=>record(q.id).attempts&&record(q.id).due<=Date.now()),stars=eligible().filter(q=>S.stars[q.id]),qs=view.reviewTab==='due'?due:view.reviewTab==='stars'?stars:wrong;return `${heading('把薄弱处，再学明白','复习可以重复，不增加整库自测的覆盖。')}${eligible().some(q=>q.type==='multi')?'<div class="top-action-row"><span class="small muted">多选：逐项判断知识边界</span>'+button('多选专项','multi-start','','light small-btn')+'</div>':''}<div class="segmented">${[['wrong','错题',wrong.length],['due','到期',due.length],['stars','收藏',stars.length]].map(([v,n,count])=>`<button class="${view.reviewTab===v?'active':''}" data-action="review-tab" data-value="${v}">${n} ${count}</button>`).join('')}</div>${qs.length?`<div class="top-action-row"><span class="small muted">${qs.length}题 · 当前题库</span>${button('练习这组','review-start',view.reviewTab,'light small-btn')}</div><div class="callout mb16">${icon('target')}<span>${view.reviewTab==='wrong'?'先看常错处：'+[...qs].sort((a,b)=>record(b.id).wrong-record(a.id).wrong).slice(0,3).map(q=>esc(q.focus)+'（错'+record(q.id).wrong+'次）').join('、'):'按自己的节奏复习，也可把题目加入笔记。'}</span></div><div class="question-list">${qs.slice(0,view.limit).map(questionCard).join('')}</div>${qs.length>view.limit?button('继续加载','review-more','','outline full mt16'):''}`:empty(view.reviewTab==='stars'?'还没有收藏':'当前没有这类复习题','学习时可以收藏和写笔记；答错的题会自动进入错题集。')}`;}
function openSession(s,{review=false,index=null}={}){
 if(!s)return toast('没有找到这份学习进度。');
 S.bank=s.bankId;selectedSessionId=s.id;
 if(index!==null)s.index=index;
 if(s.kind==='study'){M.touch(S,s);save();close();go('quiz');return;}
 const summary=M.sessionSummary(s);
 if(review){s.phase='review';M.touch(S,s);save();close();go('result');return;}
 if(!summary.blank&&s.submissions?.length){M.touch(S,s);save();close();go('result');return;}
 s.phase='answering';
 if(s.submissions?.length&&index===null){const first=s.ids.findIndex(id=>!s.responses[id]);if(first>=0)s.index=first;}
 M.touch(S,s);save();close();go('quiz');
}
function beginReview(qs,title){
 const list=qs.filter(q=>!q.excluded).sort((a,b)=>(record(a.id).last||0)-(record(b.id).last||0)||record(a.id).attempts-record(b.id).attempts).slice(0,20);if(!list.length)return toast('没有符合条件的题目。');
 const id=M.uid(),s={id,kind:'review',bankId:S.bank,title,ids:M.shuffle(list.map(q=>q.id),id),index:0,seed:id,drafts:{},responses:{},readIds:[],createdAt:Date.now(),updatedAt:Date.now(),phase:'answering',submissions:[]};S.sessions[id]=s;openSession(s);
}
function move(index){const s=current();if(!s||index<0||index>=s.ids.length)return;s.index=index;M.touch(S,s);save();close();render();window.scrollTo(0,0);}
function lettersFor(q,ids,s=current()){const perm=s?M.permutation(s,q):[...q.options.keys()];return(ids||[]).map(i=>letter(perm.indexOf(i))).sort().join('、');}
function sourceBlock(q){return `<details class="source"><summary>资料定位 · 第${q.chapter}章${q.sourcePages?.length?' · 第'+q.sourcePages.join('、')+'页':''}</summary><p>${esc(chapter(q.chapter).title)}<br>${esc(q.sourceSection||'原题库解析')}<br>${esc(q.sourceEvidence||'原题库保留内容，请结合本章资料核对。')}</p>${textButton('查看本章学习要点'+icon('chevron'),'chapter-source',q.chapter)}</details>`;}
function explanation(q,r,study=false){
 const selected=r?.selected||[],missing=q.answers.filter(n=>!selected.includes(n)),extra=selected.filter(n=>!q.answers.includes(n));
 const title=study?'答案与解析':r?.correct?'答对了':q.type==='multi'?(missing.length&&extra.length?'有错选，也有漏选':missing.length?'有漏选，注意完整性':'有多选，注意边界'):'这题值得再看一次';
 return `<section class="feedback" id="feedback" aria-live="polite"><div class="feedback-title ${!study&&!r?.correct?'wrong':''}">${icon(study?'book':r?.correct?'check':'review')}${title}</div><div class="answer-strip">正确答案 <b>${lettersFor(q,q.answers)}</b>${study?'学习模式 · 不计成绩':'你的答案 '+lettersFor(q,selected)}</div><p class="explanation ${q.explanation?'':'muted'}">${esc(q.explanation||'无解析')}</p>${q.caution?`<div class="source-flag">${esc(q.caution)}${q.correctionUrl&&/^https:\/\//.test(q.correctionUrl)?`<br><a href="${esc(q.correctionUrl)}" target="_blank" rel="noopener noreferrer">核对来源 ↗</a>`:''}</div>`:''}${sourceBlock(q)}${S.notes[q.id]?`<div class="note-display">${esc(S.notes[q.id])}</div>`:''}<div class="quiz-tools"><button data-action="note" data-value="${esc(q.id)}">${icon('note')}${S.notes[q.id]?'编辑笔记':'写一句笔记'}</button><button data-action="question-issue" data-value="${esc(q.id)}">${icon('flag')}记录疑问</button></div></section>`;
}
function quiz(){
 const s=current(),q=currentQ();if(!s||!q)return empty('学习进度暂不可用','返回目录重新选组，原记录仍会保留。');
 const study=s.kind==='study';if(study){M.markRead(S,s,q.id);save();}
 const r=s.responses[q.id],draft=s.drafts[q.id]||{selected:[],uncertain:false},perm=M.permutation(s,q),graded=!!r,reviewing=s.phase==='review',locked=study||graded;
 const selected=study?q.answers:graded?r.selected:draft.selected;
 const count=study?s.ids.filter(id=>S.reading[id]).length:s.ids.filter(id=>s.responses[id]||s.drafts[id]?.selected?.length).length;
 const summary=M.sessionSummary(s),instant=s.kind==='review'||s.kind==='legacy-practice';
 const showFeedback=study||graded&&(reviewing||instant||summary.blank>0&&s.submissions?.length);
 let footer;
 if(study)footer=button(s.index===s.ids.length-1?'本组学习回顾'+icon('arrow'):'下一题'+icon('arrow'),s.index===s.ids.length-1?'study-finish':'next','','primary');
 else if(reviewing&&!graded)footer=button('补答这题','answer-blank','','primary');
 else if(instant&&!graded)footer=button('提交答案','instant-submit','','primary');
 else footer=button(s.index===s.ids.length-1?(reviewing?'返回结果':'保存并交卷'):'下一题'+icon('arrow'),s.index===s.ids.length-1?(reviewing?'result-open':'finish-prompt'):'next','','primary');
 return `<div class="quiz-container"><header class="quiz-header"><button class="icon-btn" data-action="quiz-exit" aria-label="保存进度并退出">${icon('back')}</button><div class="center"><b>${esc(s.title)}</b><p>${study?'学习模式 · 已看':'本机已保存 · 已选'} ${count}/${s.ids.length}${study?' · 不计成绩':''}</p></div><button class="quiz-directory" data-action="answer-card" aria-label="${study?'题目目录':'答题卡与交卷'}">${icon('grid')}<span>${study?'目录':'答题卡'}</span></button></header><div class="quiz-progress"><span style="width:${count/s.ids.length*100}%"></span></div><main id="main"><div class="row between mb16"><span class="small muted">第 <strong class="mono" style="font-size:21px;color:var(--ink)">${String(s.index+1).padStart(2,'0')}</strong> / ${s.ids.length} 题</span><button class="icon-btn ${S.stars[q.id]?'active':''}" data-action="star" data-value="${esc(q.id)}" aria-label="${S.stars[q.id]?'取消收藏':'收藏本题'}" aria-pressed="${!!S.stars[q.id]}">${icon('star')}</button></div><div class="quiz-meta">${tag(study?'看题学习':s.kind==='coverage'?'整库自测':s.kind==='group-test'?'组内自测':'复习练习')}${tag(q.type==='multi'?'多选':'单选',q.type==='multi'?'blue':'neutral')}<span class="tiny muted">第${q.chapter}章</span><span class="qid">${esc(q.displayId||q.id)}</span></div><h1 class="quiz-stem">${esc(q.stem)}</h1><p class="quiz-hint">${study?'正确答案已选中，可直接阅读解析。':reviewing&&!graded?'本题未作答，尚未计入覆盖。':q.type==='multi'?'有两个或以上正确项，全部选对才计正确。':'请选择一个最符合题意的答案。'}${!study&&!instant&&!reviewing?'交卷后统一查看解析。':''}</p>${study?`<div class="row between mb16">${tag('答案 '+lettersFor(q,q.answers))}${textButton((q.explanation?'看解析':'无解析 · 查看来源')+icon('down'),'jump-explanation')}</div>`:''}<div class="choices" role="group" aria-label="${study?'已标出正确答案':'选择答案'}">${perm.map((original,i)=>{const chosen=selected.includes(original),right=q.answers.includes(original),showRight=study||showFeedback;return `<button class="choice ${q.type==='multi'?'multi':''} ${showRight?(right?'correct':chosen?'incorrect':''):chosen?'selected':''}" data-action="choose" data-value="${original}" aria-pressed="${chosen}" ${locked||reviewing?'disabled':''}><span class="choice-key">${study&&right?icon('check'):letter(i)}</span><span class="choice-text">${esc(q.options[original])}</span>${showRight&&(right||chosen)?`<span class="choice-mark">${right?study?'正确答案':chosen?'选对':'正确项':'错选'}</span>`:''}</button>`;}).join('')}</div>${showFeedback?explanation(q,r,study):reviewing&&!graded?`<div class="callout mt16">${icon('info')}<span>未答题不会算作已测或错题。补答后重新交卷，新增答案才会计入覆盖，首测成绩保留。</span></div>`:`<div class="quiz-tools"><button class="${draft.uncertain?'active':''}" data-action="uncertain" aria-pressed="${draft.uncertain}">${icon('flag')}${draft.uncertain?'已标记：没把握':'这题没把握'}</button><span class="tiny muted">选择即保存，可从题目目录返回修改</span></div>`}</main></div><footer class="quiz-footer"><div class="quiz-footer-inner"><button class="secondary" data-action="prev" ${s.index===0?'disabled':''}>上一题</button>${footer}${!study&&!instant&&!reviewing?'<button class="secondary submit-shortcut" data-action="finish-prompt">交卷</button>':''}</div><p class="quiz-bottom-note">${study?'已看进度独立保存 · 不计答题成绩':reviewing?'本次已交卷 · 浏览解析不重复计数':s.kind==='coverage'?'交卷后计入本轮覆盖 · 未答不计覆盖':'学习进度已保存到本机 · 可随时中断'}</p></footer>`;
}
function promptSubmit(){
 const s=current();if(!s)return;
 const fresh=s.ids.filter(id=>!s.responses[id]&&s.drafts[id]?.selected?.length).length,blank=s.ids.filter(id=>!s.responses[id]&&!s.drafts[id]?.selected?.length).length;
 if(!fresh){if(s.submissions?.length){close();go('result');return;}sheet('进度已保存',`<p>还没有新答案可提交。可以继续答题，或保存进度后退出。</p><div class="sheet-footer">${button('继续作答','close','','outline')}${button('保存并退出','quiz-exit')}</div>`);return;}
 sheet(blank?'还有 '+blank+' 题未答':'准备交卷',`<p>本次提交 ${fresh} 道新答案。${blank?'未答题将保留待补测，不计覆盖，也不进入错题集。':'交卷后统一查看成绩和解析。'}${s.submissions?.length?'之前的首测成绩会保留，已提交的题目不会重复计数。':''}</p><div class="sheet-footer">${button(blank?'继续作答':'再检查一下',blank?'first-blank':'close','','outline')}${button(blank?'交卷，未答留待补测':'确认交卷','submit')}</div>`);
}
function finishSubmit(){const s=current(),r=M.submit(S,s,qmap);if(!r.newAnswers)return toast('没有需要重复提交的新答案。');save();close();go('result');}
function result(){
 const s=current();if(!s)return empty('没有选择自测记录','先在目录中选择一组或一卷。','tests','查看自测计划');
 if(s.kind==='study'){
  const seen=s.ids.filter(id=>S.reading[id]).length,g=s.groupId&&group(s.groupId),next=groups()[groups().findIndex(x=>x.id===s.groupId)+1];
  return `<div class="quiz-container"><header class="quiz-header"><button class="icon-btn" data-action="quiz-exit" aria-label="返回学习目录">${icon('back')}</button><span class="small muted">${esc(s.title)} · 学习回顾</span><span style="width:44px"></span></header><main id="main"><div class="result-top"><div class="result-icon">${icon('book')}</div><h1>${seen===s.ids.length?'看完一组，测清一组。':'这一组，随时接着看。'}</h1><p>已看 ${seen}/${s.ids.length} 题，只记录学习进度，不计成绩。</p></div><div class="grid2">${g?button('测这一组'+icon('test'),'group-test',g.id):button('练习这组','test-study-session')}${next?button('下一学习组','study-group',next.id,'light'):button('回章节目录','nav','groups','light')}</div>${section('本组题目')}${resultQuestionList(s,true)}</main></div>`;
 }
 const r=M.sessionSummary(s),first=s.submissions?.[0],wrong=s.ids.filter(id=>s.responses[id]&&!s.responses[id].correct),round=s.roundId&&(S.rounds[s.bankId]||[]).find(x=>x.id===s.roundId),rt=round&&M.roundStats(S,round),typeData=['single','multi'].map(type=>{const ids=s.ids.filter(id=>qmap.get(id)?.type===type);return{type,total:ids.length,correct:ids.filter(id=>s.responses[id]?.correct).length};});
 const multiWrong=wrong.filter(id=>qmap.get(id).type==='multi'),missing=multiWrong.filter(id=>qmap.get(id).answers.some(n=>!s.responses[id].selected.includes(n))).length,extra=multiWrong.filter(id=>s.responses[id].selected.some(n=>!qmap.get(id).answers.includes(n))).length;
 return `<div class="quiz-container"><header class="quiz-header"><button class="icon-btn" data-action="quiz-exit" aria-label="返回自测计划">${icon('back')}</button><span class="small muted">${esc(s.title)} · 结果</span><span style="width:44px"></span></header><main id="main"><div class="result-top"><div class="result-icon">${icon(r.blank?'book':'check')}</div><h1>${r.blank?'进度已保留，未答可补测。':'完成了，回看薄弱处。'}</h1><p>${wrong.length?'答错的题已进入错题集。':'把这次理解留给之后的复习巩固。'}</p><div class="result-score">${r.score}<span> / 100 分</span></div><p>本组每题等权 · 未答记0分，覆盖另计</p></div><div class="result-stats"><div><b>${r.correct}</b><small>答对</small></div><div><b>${r.wrong}</b><small>答错</small></div><div><b>${r.blank}</b><small>未答</small></div><div><b>${r.answered}</b><small>已提交</small></div></div>${rt?`<div class="callout mb16">${icon('layers')}<span>第${round.number}轮累计覆盖 <strong>${rt.covered}/${rt.total}</strong> 题，剩 ${rt.remaining} 题。未答部分补测后再计入。</span></div>`:s.kind==='group-test'?`<div class="callout info mb16">${icon('info')}<span>这次属于组内自测，整库自测覆盖数保持独立。</span></div>`:''}${first&&s.submissions.length>1?`<p class="small muted mb16">首次交卷 ${first.score}分（${first.answered}题已答）；上方为补答后的当前成绩。历次交卷记录均保留。</p>`:''}<div class="result-breakdown">${typeData.filter(x=>x.total).map(x=>`<div><span>${x.type==='single'?'单选答对':'多选答对'}</span><strong>${x.correct}/${x.total}</strong></div>`).join('')}${multiWrong.length?`<p class="tiny muted">多选薄弱点：${missing}题有漏选，${extra}题有多选；同一道题可能两者都有。</p>`:''}</div><div class="grid2 mt16">${r.blank?button('补答 '+r.blank+' 道未答题','supplement'):button('逐题看解析','review-session','','light')}${wrong.length?button('复习本组错题','review-session-wrong','','outline'):button('返回自测计划','nav','tests','outline')}</div>${r.blank?`<div class="mt8">${textButton('先看已答题解析','review-session')}</div>`:''}${section('题目与解析',s.submissions?.length>1?textButton('历次交卷','submission-history'):'' )}${resultQuestionList(s,false)}</main></div>`;
}
function resultQuestionList(s,study){return `<div class="question-list">${s.ids.map((id,index)=>{const q=qmap.get(id),r=s.responses[id];return `<button class="question-item" data-action="result-question" data-value="${index}"><div class="row">${tag(study?(S.reading[id]?'已看':'未看'):!r?'未答':r.correct?'答对':'答错',!study&&r&&!r.correct?'red':'')}<span class="meta">${esc(q.displayId||id)} · ${q.type==='multi'?'多选':'单选'}</span></div><p>${esc(q.stem)}</p></button>`;}).join('')}</div>`;}
function answerCard(){const s=current(),study=s.kind==='study';sheet(study?'学习题目目录':'答题卡',`<p class="small muted mb16">${study?'已看 '+s.ids.filter(id=>S.reading[id]).length:'已选 '+s.ids.filter(id=>s.responses[id]||s.drafts[id]?.selected?.length).length}/${s.ids.length} · 点击跳转</p><div class="answer-grid">${s.ids.map((id,i)=>{const r=s.responses[id],done=study?S.reading[id]:r||s.drafts[id]?.selected?.length;return `<button class="${done?s.phase==='review'&&r&&!r.correct?'wrong':'answered':''} ${i===s.index?'current':''}" data-action="jump" data-value="${i}" aria-label="第${i+1}题${done?'，已有进度':''}">${i+1}</button>`;}).join('')}</div><div class="sheet-footer">${button(study?'继续学习':'继续作答','close','','outline')}${button(study?'学习回顾':s.phase==='review'?'返回结果':'交卷',study?'study-finish':s.phase==='review'?'result-open':'finish-prompt')}</div>`);}
function historyRows(){
 const fresh=Object.values(S.sessions).flatMap(s=>(s.submissions||[]).map(x=>({...x,title:s.title,sessionId:s.id,bankId:s.bankId,at:x.at})));
 const legacy=(S.legacyHistory||[]).map(h=>({...h,title:'旧版 · '+h.title,at:h.finished,legacy:true}));
 const all=[...fresh,...legacy].sort((a,b)=>(b.at||0)-(a.at||0));
 return all.length?`<div class="settings-list">${all.slice(0,12).map(h=>`<button class="setting-row" data-action="${h.sessionId?'history-open':'legacy-info'}" data-value="${esc(h.sessionId||'')}"><div class="grow"><h3>${esc(h.title)}</h3><p>${prettyTime(h.at)}${h.legacy?' · 旧记录，不计新轮覆盖':''}</p></div><span class="value">${h.correct??0}/${h.total??0} 答对</span>${icon('chevron')}</button>`).join('')}</div>`:empty('自测记录会留在这里','每次交卷都会保留。重新一轮，不会清空此前成绩。','tests','进入自测');
}
function me(){
 const read=Object.keys(S.reading).length,attempts=Object.values(S.records).reduce((n,r)=>n+r.attempts,0),right=Object.values(S.records).reduce((n,r)=>n+r.right,0);
 return `${heading('学习有记录，进步有依据','题目覆盖按去重统计，累计答题次数另行保留。')}<div class="stats-card"><div class="hero-stats" style="margin-top:0"><div class="hero-stat"><b>${read}</b><small>累计已看 · 全题库</small></div><div class="hero-stat"><b>${attempts}</b><small>累计作答次数</small></div><div class="hero-stat"><b>${attempts?Math.round(right/attempts*100)+'%':'—'}</b><small>累计正确率</small></div></div></div>${section('手动云端同步')}<button class="cloud-card" data-action="sync-open"><span class="mode-icon">${icon('cloud')}</span><div class="grow"><h3>点一下，再交换进度</h3><p>${esc(syncStatus())}<br>使用免费GitHub私有仓库，不做后台自动同步。</p></div>${icon('chevron')}</button>${section('进度与题库')}<div class="settings-list">${settingRow('download','导出学习备份','包含已看、全部分组、轮次、错题、收藏和笔记','export-backup')}${settingRow('upload','恢复学习备份','支持旧版v4，可选择合并或替换','import-backup')}${settingRow('layers','切换题库',banks.length+'套题库，计划与覆盖分别记录','banks')}${settingRow('upload','导入新题库','JSON格式；自动按章节固定分组','bank-import-guide')}${settingRow('download','导出当前题库','包含答案、有效解析及原文页码','export-bank')}</div>${section('按你的阅读习惯')}<div class="settings-list">${settingRow('target','每日新看目标','只影响每日目标，不改变已固定分组','goal',S.settings.goal+'题')}${settingRow('book','题目字号','适合手机阅读的题干和选项大小','font',S.settings.font===21?'特大':S.settings.font===19?'大':'标准')}${settingRow('device','添加到手机主屏幕','首次联网完整打开后可离线使用','install')}</div>${section('最近自测与交卷')}${historyRows()}${section('资料与规则')}<div class="settings-list">${settingRow('shield','资料版本与勘误','完整20章、43页原文；暂缓题单独列明','source-info')}${settingRow('info','进度和自测规则','已看、组内自测、整库轮次分别统计','rules')}${settingRow('trash','清除本机学习记录','先导出备份；不会删除云端记录或内置题库','reset-prompt')}</div><p class="footer-note">低空研习 2.0 · GitHub Pages 免费静态网站<br>平时只存本机；只有你点击同步时才连接GitHub。<br>本工具的学习自测规则不代表官方认证考试规则。</p>`;
}
function settingRow(i,title,description,action,value=''){return `<button class="setting-row" data-action="${action}">${icon(i)}<div class="grow"><h3>${title}</h3><p>${description}</p></div>${value?`<span class="value">${value}</span>`:''}${icon('chevron')}</button>`;}
function bankSheet(){sheet('选择题库',`<p class="muted">学习分组、各轮自测和覆盖率都按题库分别记录。</p>${banks.map(b=>`<button class="bank-choice ${b.id===S.bank?'active':''}" data-action="bank-select" data-value="${esc(b.id)}"><div class="row between"><h3>${esc(b.name)}</h3>${b.id===S.bank?icon('check'):''}</div><p>${b.questions.filter(q=>!q.excluded).length}道可用题 · ${b.questions.filter(q=>q.type==='single').length}单选 / ${b.questions.filter(q=>q.type==='multi').length}多选<br>已看 ${M.bankStats(S,b).read}题 · ${S.plans[b.id]?.groups.length||0}组</p></button>`).join('')}${button('导入其他题库','bank-import-guide','','outline full')}`);}
function chapterSource(n){const c=chapter(n);sheet(c.title,`${c.hint?`<div class="callout">${icon('target')}<span>${esc(c.hint)}</span></div>`:''}${(c.sections||[]).map(p=>`<h3>${esc(p.title)}</h3><p style="white-space:pre-line">${esc(p.text)}</p>`).join('')}<p class="tiny muted mt16">来源：用户提供并经43页原课程全文核对的学习指引。阶段性产品和手册参数按课程版本理解。</p>`);}
function peek(id){const q=qmap.get(id);if(!q)return;const p=paperFor(id);sheet((q.type==='multi'?'多选':'单选')+' · '+(q.displayId||id),`<div class="row">${tag('第'+q.chapter+'章')}${tag(S.reading[id]?'已看':'未看','neutral')}</div><h3 style="font-size:17px;line-height:1.9">${esc(q.stem)}</h3>${q.options.map((o,i)=>`<p class="mt8">${letter(i)}. ${esc(o)}</p>`).join('')}${q.excluded?`<div class="callout warning mt16">${icon('info')}<span>${esc(q.caution||'本题暂缓用于学习与自测。')}</span></div>${sourceBlock(q)}`:`<div class="sheet-footer">${button('看答案学习','study-one',id,'light')}${view.type==='uncovered'&&p?button('到第'+p.number+'卷补答','paper-question',id):button('单题练习','practice-one',id)}</div><p class="tiny muted mt8">单题练习与错题复习不会增加整库本轮覆盖。</p>`}<div class="mt8">${textButton((S.stars[id]?'取消收藏':'收藏这题')+icon('star'),'star-peek',id)}</div>`);}
function rules(){sheet('学习与自测，怎样计算',`<h3>已看</h3><p>进入学习题目就记录已看。重复查看同一题不增加累计题数；已看不代表已会做。</p><h3>固定分组</h3><p>分组保留章节边界，每组约15题、最多18题，章内均衡。每个小组分别保存断点，不会被另一次学习覆盖。</p><h3>两种自测</h3><p>组内自测考同一个学习组；整库自测每卷50题，整轮的各卷之间无重复、无漏题。两种覆盖分开记录，互不抵扣。每次测题会打乱题序或选项，答案仍按选项内容判定。</p><h3>交卷与补答</h3><p>交卷后，实际作答的题计入覆盖。未答保留待补测，不入错题；答错算已测，同时进入复习。补答只计新增答案，首次交卷成绩保留。</p><h3>重新一轮</h3><p>只新建分卷和本轮覆盖，不删除旧轮成绩、已看、错题、收藏或笔记。可在轮次列表切回旧轮查看或继续。</p><h3>错题与间隔复习</h3><p>答错进入错题集，在两个不同日期各有一次有把握地答对后移出，期间答错重新计算。正确题按1、3、7、14、30天安排复习；答错或没把握后10分钟再看。同一天反复答对不累加掌握日期。</p><h3>保存与同步</h3><p>平时只保存到当前浏览器。只有点击“同步一次”，才把本机与GitHub私有仓库的数据合并保存。导出备份不包含访问钥匙。</p>`);}
function sourceInfo(){sheet('资料版本与勘误',`<p>${esc(D.sourceNote)}</p><h3>题库</h3><p>原500题与新500题分别保留。新题包含300单选、200多选；每题可查看原文依据与页码。没有额外教学信息的解析显示“无解析”。</p>${D.issues.map(x=>`<p class="mt8">• ${esc(x.text)}${x.url?` <a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">核对来源 ↗</a>`:''}</p>`).join('')}<h3>重点提醒</h3><p>资料重点依据课程考核提示；个人常错依据本机及手动合并的答题记录。不宣称真实考试频率。</p>`);}
const TOKEN_SESSION='l3-sync-key-session',TOKEN_REMEMBER='l3-sync-key-remember';
let memoryToken='';
function getToken(){try{return memoryToken||sessionStorage.getItem(TOKEN_SESSION)||localStorage.getItem(TOKEN_REMEMBER)||'';}catch{return memoryToken;}}
function keepToken(token,remember){memoryToken=token;try{if(remember){localStorage.setItem(TOKEN_REMEMBER,token);sessionStorage.removeItem(TOKEN_SESSION);}else{sessionStorage.setItem(TOKEN_SESSION,token);localStorage.removeItem(TOKEN_REMEMBER);}}catch{toast('此浏览器不能记住钥匙，本次仍可使用。');}}
function forgetToken(){memoryToken='';try{sessionStorage.removeItem(TOKEN_SESSION);localStorage.removeItem(TOKEN_REMEMBER);}catch{}const input=$('#cloud-key');if(input)input.value='';toast('已忘记本机钥匙，云端记录保留。');}
function syncOpen(){
 const cfg=S.sync;
 const tokenUrl='https://github.com/settings/personal-access-tokens/new?'+new URLSearchParams({name:'L3-study-progress',description:'Manual sync for one private progress repository',target_name:cfg.owner,expires_in:'90',contents:'write'});
 sheet('手动云端同步',`<div class="callout">${icon('cloud')}<span>只在你点“同步一次”时连接GitHub，读取两端记录、合并后保存。不会后台自动同步，也不会开通付费云服务。</span></div><div class="sync-location"><span class="tiny muted">你的云端存放位置</span><strong>${esc(cfg.owner)} / ${esc(cfg.repo)}</strong><small>必须是私有仓库；首次成功写入前，不会显示“已同步”。</small></div><details class="setup-guide" ${getToken()?'':'open'}><summary>首次使用：只需准备一把访问钥匙</summary><ol><li>点击下面的“创建访问钥匙”，在GitHub登录自己的账号。</li><li>找到 <b>Repository access</b>，选择 <b>Only select repositories</b>，只勾选 <b>${esc(cfg.repo)}</b>。</li><li>在 <b>Repository permissions → Contents</b> 选择 <b>Read and write</b>，其他权限保持默认。</li><li>点击 <b>Generate token</b>，复制生成的长码，回到这里粘贴。<b>不用发给任何人或发在聊天里。</b></li></ol><a class="btn outline small-btn" href="${esc(tokenUrl)}" target="_blank" rel="noopener noreferrer">创建访问钥匙 ↗</a><p class="tiny muted mt8">GitHub免费私有仓库即可使用，不需要绑定支付方式。钥匙到期后需要换新；不会自动扣费或升级套餐。</p></details><label class="form-label" for="cloud-key">粘贴访问钥匙</label><input class="form-input" id="cloud-key" type="password" autocomplete="off" spellcheck="false" placeholder="以 github_pat_ 开头的长码"><label class="remember-key"><input id="remember-key" type="checkbox">在这台个人设备记住钥匙</label><p class="tiny muted">不勾选则仅当前标签页临时保存，关闭后需重输。钥匙不进入公开代码、学习备份或云端进度文件；可随时点“忘记钥匙”清除。</p><details class="advanced-config"><summary>更改连接位置（一般不用）</summary><label class="form-label" for="sync-owner">GitHub账号</label><input class="form-input" id="sync-owner" value="${esc(cfg.owner)}" autocomplete="off"><label class="form-label" for="sync-repo">私有仓库名称</label><input class="form-input" id="sync-repo" value="${esc(cfg.repo)}" autocomplete="off"></details><div class="sync-status" id="sync-status" role="status">${S.sync.lastSuccessAt?'上次成功同步：'+prettyTime(S.sync.lastSuccessAt):'在手机日常网络下点击同步即可验证连接。未连接成功时，本机进度始终保留。'}</div><div class="sheet-footer">${button('忘记钥匙','sync-forget','','outline')}${button('同步一次','sync-run')}</div><p class="tiny muted mt16">合并会保留两端不同题目的进度、笔记和全部轮次。较新的取消收藏或笔记修改会保留；不会整份覆盖另一台设备。</p>`);
 $('#cloud-key').value=getToken();try{$('#remember-key').checked=!!localStorage.getItem(TOKEN_REMEMBER);}catch{}
}
async function runSync(){
 if(syncController)return;
 const status=$('#sync-status');let cfg;
 try{cfg=C.config({...S.sync,owner:$('#sync-owner').value,repo:$('#sync-repo').value});}catch(e){status.textContent=e.message;status.classList.add('error');return;}
 const token=$('#cloud-key').value.trim(),remember=$('#remember-key').checked;
 if(!token)return status.textContent='先按上面的步骤创建访问钥匙，并粘贴到这里。';
 keepToken(token,remember);S.sync={...S.sync,...cfg,mode:'manual'};save();
 const snapshot=M.snapshot(S),start=S.updatedAt;syncController=new AbortController();const controller=syncController;
 $('#sheet [data-action="sync-run"]').disabled=true;status.classList.remove('error');
 const timeout=setTimeout(()=>controller.abort(),45000);
 try{
  const answer=await C.manualSync({state:snapshot,banks:D.banks,settings:cfg,token,signal:controller.signal,onStep:text=>{if($('#sync-status'))$('#sync-status').textContent=text+'…';}});
  const changed=S.updatedAt>start,now=Date.now();S=M.merge(S,answer.state,D.banks,now);S.sync={...S.sync,...cfg,verified:true,mode:'manual',lastSuccessAt:now,lastSyncedAt:changed?start:now};rebuild();save();
  if($('#sync-status')){$('#sync-status').textContent=changed?'本次合并已成功。同步期间又有本机新记录，需要时再点一次即可。':'同步成功，两端进度已合并保存。另一台设备也点“同步一次”即可获取。';$('#sync-status').classList.add('success');}
  render();toast('手动同步成功，进度已合并。');
 }catch(e){if($('#sync-status')){$('#sync-status').textContent=e.message;$('#sync-status').classList.add('error');}else toast(e.message);}
 finally{clearTimeout(timeout);if(syncController===controller)syncController=null;const b=$('#sheet [data-action="sync-run"]');if(b)b.disabled=false;}
}
function bankImportGuide(){sheet('导入JSON题库',`<p>每套最多5000题，单选或多选均可；解析可省略。导入后自动建立固定章节小组和独立自测计划。</p><pre>${esc(JSON.stringify({name:'我的题库',questions:[{id:'1',chapter:1,type:'single',stem:'示例题干',options:['选项一','选项二','选项三','选项四'],answers:[0],explanation:null}]},null,2))}</pre><p class="tiny muted">答案编号从0开始；多选至少两个正确项。知识准确性由题库提供者保证。</p>${button('选择JSON题库','bank-file','','full mt16')}`);}
async function readFile(file){if(!file)return null;if(file.size>20*1024*1024)throw Error('文件超过20MB，请先整理后再导入。');try{return JSON.parse(await file.text());}catch{throw Error('文件不是有效JSON。');}}
async function prepareBank(file){try{const b=M.validateBank(await readFile(file));pending={kind:'bank',data:b};sheet('确认导入题库',`<h3>${esc(b.name)}</h3><p class="mt8">共 ${b.questions.length} 题：${b.questions.filter(q=>q.type==='single').length}单选，${b.questions.filter(q=>q.type==='multi').length}多选。</p><p class="small muted mt16">格式检查通过，导入不会覆盖内置题库或已有学习数据。</p><div class="sheet-footer">${button('取消','close','','outline')}${button('导入并切换','bank-confirm')}</div>`);}catch(e){toast(e.message);}}
function confirmBank(){if(pending?.kind!=='bank')return;const data=pending.data,id='u-'+M.uid(),b={id,name:data.name.trim(),shortName:data.name.trim(),description:'本机导入题库',questions:data.questions.map((q,i)=>({id:id+':'+(i+1),displayId:String(q.id??i+1),chapter:q.chapter,type:q.type,stem:q.stem.trim(),options:[...q.options],answers:[...q.answers],explanation:q.explanation||null,focus:typeof q.focus==='string'?q.focus:'自定义考点',difficulty:['基础','应用','进阶'].includes(q.difficulty)?q.difficulty:'应用',sourceSection:typeof q.sourceSection==='string'?q.sourceSection:'用户导入题库',sourceEvidence:typeof q.sourceEvidence==='string'?q.sourceEvidence:'',sourcePages:Array.isArray(q.sourcePages)?q.sourcePages.filter(n=>Number.isInteger(n)&&n>0&&n<10000):[]}))};S.customBanks.push(b);S.bank=id;S.updatedAt=Date.now();rebuild();save();pending=null;close();view.chapter=null;view.libraryTab='chapters';go('groups');toast('题库已导入，固定分组已建立。');}
async function prepareBackup(file){try{const b=await readFile(file);if(b?.kind!=='low-altitude-study-backup'||![4,5].includes(b.version)||!b.state)throw Error('这不是本工具支持的学习备份。');M.validateState(b.state,D.banks);const state=M.migrate(b.state,D.banks);pending={kind:'backup',state};sheet('恢复学习备份',`<p>备份时间：${esc(b.exportedAt||'未知')}<br>已看 ${Object.keys(state.reading).length} 题，${Object.keys(state.records).length} 道有答题记录，${state.customBanks.length} 套自定义题库。</p><div class="callout mt16">${icon('info')}<span>推荐合并恢复，保留两份数据。旧版随机自测只保留历史，不会充入新的整轮覆盖。</span></div><div class="sheet-footer">${button('合并到本机','backup-merge')}${button('替换当前记录','backup-replace-prompt','','outline')}</div>`);}catch(e){toast(e.message);}}
function restoreBackup(replace){if(pending?.kind!=='backup')return;const next=pending.state;if(replace)S=next;else S=M.merge(S,next,D.banks);saveBlocked=false;rawRecovery=null;rebuild();save();pending=null;close();go('me');toast(replace?'学习备份已恢复。':'备份已与本机记录合并。');}
function newRoundPrompt(){const n=eligible().length,r=coverage(),x=M.roundStats(S,r);sheet(r?'开启新一轮自测':'创建第1轮自测计划',`<p>${n} 道可用题分成 ${Math.ceil(n/50)} 卷，每卷最多50题。每轮一次性分卷，各卷之间不重复，默认不限时。</p>${r?`<div class="callout mt16">${icon('layers')}<span>当前第${r.number}轮已覆盖 ${x.covered}/${x.total}。新轮会保留旧轮的全部成绩与未完成进度，也保留学习、错题、收藏和笔记。</span></div>`:''}<div class="sheet-footer">${button('取消','close','','outline')}${button(r?'创建第'+((S.rounds[S.bank]||[]).length+1)+'轮':'创建第1轮','round-create')}</div>`);}
function historyOpen(id){const s=S.sessions[id];if(s){selectedSessionId=id;S.bank=s.bankId;save();go('result');}}
const actions={
 'nav':el=>{close();if(el.dataset.value==='groups')view.libraryTab='chapters';go(el.dataset.value);},'close':close,'banks':bankSheet,
 'bank-select':el=>{S.bank=el.dataset.value;save();view.chapter=null;view.groupFilter='all';view.search='';view.type='all';view.limit=40;selectedSessionId=null;close();if(['quiz','result'].includes(view.page))go('home');else render();toast('已切换题库。');},
 'migration-seen':()=>{S.migration.noticeSeen=true;save();render();},
 'chapter-open':el=>{view.chapter=+el.dataset.value;view.groupFilter='all';view.libraryTab='chapters';go('groups');},'chapter-back':()=>{view.chapter=null;render();},'group-filter':el=>{view.groupFilter=el.dataset.value;render();},
 'library-search':()=>{view.libraryTab='questions';view.type='all';view.limit=40;render();},'library-chapters':()=>{view.libraryTab='chapters';render();},'search-type':el=>{view.type=el.dataset.value;view.limit=40;$('#question-results').innerHTML=searchResults();document.querySelectorAll('[data-action="search-type"]').forEach(b=>b.classList.toggle('active',b.dataset.value===view.type));},'load-more':()=>{view.limit+=40;$('#question-results').innerHTML=searchResults();},
 'study-group':el=>{const g=group(el.dataset.value);if(g)openSession(M.studySession(S,bank(),g));},'group-test':el=>{const g=group(el.dataset.value);if(g)openSession(M.groupTestSession(S,bank(),g));},'group-retest':el=>{const g=group(el.dataset.value);if(g)openSession(M.groupTestSession(S,bank(),g,{newAttempt:true}));},
 'session-open':el=>openSession(S.sessions[el.dataset.value]),'history-open':el=>historyOpen(el.dataset.value),'legacy-info':()=>sheet('旧版历史记录','<p>这条旧版记录只保存了成绩汇总，无法还原当时完整题单。它已保留为历史，不用于证明新轮的题目覆盖。</p>'),
 'test-tab':el=>{view.testTab=el.dataset.value;render();},'round-new':newRoundPrompt,'round-create':()=>{M.createRound(S,bank());save();close();view.testTab='coverage';go('tests');toast('整轮题目已固定，各卷无重复。');},
 'paper-open':el=>{const r=coverage(),p=r?.papers.find(p=>p.id===el.dataset.value);if(p)openSession(M.paperSession(S,bank(),r,p));},'paper-question':el=>{const r=coverage(),p=paperFor(el.dataset.value);if(p)openSession(M.paperSession(S,bank(),r,p),{index:p.ids.indexOf(el.dataset.value)});},
 'uncovered':()=>{view.libraryTab='questions';view.type='uncovered';view.search='';view.limit=40;go('groups');},
 'study-one':el=>{const q=qmap.get(el.dataset.value);if(!q||q.excluded)return;const id=M.uid(),s={id,kind:'study',bankId:S.bank,title:'单题学习',ids:[q.id],index:0,seed:id,drafts:{},responses:{},readIds:[],createdAt:Date.now(),phase:'studying',submissions:[]};S.sessions[id]=s;openSession(s);},
 'practice-one':el=>{const q=qmap.get(el.dataset.value);if(q)beginReview([q],'单题练习');},'test-study-session':()=>beginReview(current().ids.map(id=>qmap.get(id)),'学后练习'),
 'peek':el=>peek(el.dataset.value),'chapter-source':el=>chapterSource(el.dataset.value),'rules':rules,'source-info':sourceInfo,
 'choose':el=>{const s=current(),q=currentQ();if(!s||s.kind==='study'||s.phase==='review'||s.responses[q.id])return;const old=s.drafts[q.id]||{selected:[],uncertain:false},n=+el.dataset.value,selected=q.type==='single'?[n]:old.selected.includes(n)?old.selected.filter(i=>i!==n):[...old.selected,n];M.setDraft(S,s,q.id,selected,old.uncertain);save();render();document.querySelector('.choice[data-value="'+n+'"]')?.focus({preventScroll:true});},
 'uncertain':()=>{const s=current(),q=currentQ(),d=s.drafts[q.id]||{selected:[],uncertain:false};M.setDraft(S,s,q.id,d.selected,!d.uncertain);save();render();},
 'prev':()=>move(current().index-1),'next':()=>move(current().index+1),'jump':el=>move(+el.dataset.value),'answer-card':answerCard,
 'study-finish':()=>{save();close();go('result');},'result-open':()=>{close();go('result');},'finish-prompt':promptSubmit,'submit':finishSubmit,
 'instant-submit':()=>{const s=current(),q=currentQ();if(!s.drafts[q.id]?.selected?.length)return toast('请先选择答案。');M.submit(S,s,qmap);s.phase='answering';save();render();setTimeout(()=>$('#feedback')?.scrollIntoView({block:'nearest',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'}),20);},
 'first-blank':()=>{const s=current(),i=s.ids.findIndex(id=>!s.responses[id]&&!s.drafts[id]?.selected?.length);move(i<0?s.index:i);},
 'answer-blank':()=>{current().phase='answering';M.touch(S,current());save();render();},
 'supplement':()=>openSession(current()),'review-session':()=>{current().phase='review';current().index=0;save();go('quiz');},'result-question':el=>{const s=current();s.index=+el.dataset.value;if(s.kind!=='study')s.phase='review';save();go('quiz');},
 'review-session-wrong':()=>{const s=current(),qs=s.ids.filter(id=>s.responses[id]&&!s.responses[id].correct).map(id=>qmap.get(id));beginReview(qs,'本组错题复习');},
 'quiz-exit':()=>{const s=current();save();close();if(s?.kind==='study'){view.libraryTab='chapters';if(s.groupId)view.chapter=group(s.groupId)?.chapter??null;go('groups');}else if(s?.kind==='review')go('review');else{view.testTab=s?.kind==='group-test'?'group':'coverage';go('tests');}toast('各组、各卷进度已分别保存到本机。');},
 'jump-explanation':()=>$('#feedback')?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'}),
 'star':el=>{M.setStar(S,el.dataset.value,!S.stars[el.dataset.value]);save();render();},'star-peek':el=>{M.setStar(S,el.dataset.value,!S.stars[el.dataset.value]);save();peek(el.dataset.value);render();},
 'note':el=>sheet('记一句自己的理解',`<p class="small muted mb16">写下判断依据或容易混淆之处。笔记保存在本机，只有手动同步时才进入你的私有仓库。</p><textarea id="note-input" maxlength="3000" aria-label="学习笔记" placeholder="用自己的话记下这道题。">${esc(S.notes[el.dataset.value]||'')}</textarea>${button('保存笔记','note-save',el.dataset.value,'full mt16')}`),
 'note-save':el=>{M.setNote(S,el.dataset.value,$('#note-input').value);save();close();render();toast('笔记已保存。');},'question-issue':el=>actions.note(el),
 'multi-start':()=>beginReview(eligible().filter(q=>q.type==='multi'),'多选专项'),'focus-start':el=>{const f=focusGroups[+el.dataset.value];if(f)beginReview(eligible().filter(q=>f.chapters.includes(q.chapter)),f.name+'专项');},
 'review-tab':el=>{view.reviewTab=el.dataset.value;view.limit=40;render();},'review-more':()=>{view.limit+=40;render();},'review-start':el=>{const mode=el.dataset.value,qs=eligible().filter(q=>mode==='stars'?S.stars[q.id]:mode==='due'?record(q.id).attempts&&record(q.id).due<=Date.now():record(q.id).activeWrong);beginReview(qs,mode==='stars'?'收藏练习':mode==='due'?'到期复习':'错题复习');},
 'excluded':()=>{const qs=questions().filter(q=>q.excluded);sheet('暂缓使用的原题',`<p>这些题仍可核对，但不计入当前 ${eligible().length} 道可用题的覆盖分母。</p>${qs.map(q=>`<h3>${esc(q.displayId||q.id)}</h3><p>${esc(q.stem)}</p><p class="small muted mt8">${esc(q.caution)}</p>`).join('')}`);},
 'submission-history':()=>{const s=current();sheet('历次交卷 · '+s.title,(s.submissions||[]).map((x,i)=>`<div class="history-row"><div><strong>${i===0?'首次交卷':'第'+(i+1)+'次交卷'}</strong><p>${prettyTime(x.at)} · 新提交${x.newAnswers}题</p></div><div>${x.score}分<br><small>已答${x.answered} / 未答${x.blank}</small></div></div>`).join(''));},
 'sync-open':syncOpen,'sync-run':runSync,'sync-forget':forgetToken,
 'export-backup':()=>{download('低空研习-学习备份-v5-'+M.day()+'.json',{kind:'low-altitude-study-backup',version:5,exportedAt:new Date().toISOString(),state:M.snapshot(S)});toast('学习备份已导出，不含访问钥匙。');},
 'import-backup':()=>{$('#backup-file').value='';$('#backup-file').click();},'backup-merge':()=>restoreBackup(false),'backup-replace-prompt':()=>sheet('替换本机学习记录？',`<p>本机现有学习记录将被这份备份替换。建议先导出当前备份，或使用“合并恢复”保留两份数据。</p><div class="sheet-footer">${button('先导出当前备份','export-backup','','outline')}${button('确认替换','backup-replace','','danger')}</div>`),'backup-replace':()=>restoreBackup(true),
 'recover-raw':()=>download('低空研习-原始记录-待恢复.json',rawRecovery||'','application/json'),
 'bank-import-guide':bankImportGuide,'bank-file':()=>{$('#bank-file').value='';$('#bank-file').click();},'bank-confirm':confirmBank,'export-bank':()=>download(bank().name+'-题库.json',{name:bank().name,questions:bank().questions}),
 'goal':()=>sheet('每日新看目标',`<p>只用于今天的新看题数，不改变固定学习组。</p><div class="filter-pills mt16">${[5,10,15,20,30].map(n=>`<button class="${S.settings.goal===n?'active':''}" data-action="goal-set" data-value="${n}">${n}题</button>`).join('')}</div>`),'goal-set':el=>{S.settings.goal=+el.dataset.value;save();close();render();},
 'font':()=>sheet('题目字号',`<div class="filter-pills">${[[17,'标准'],[19,'大'],[21,'特大']].map(([n,label])=>`<button class="${S.settings.font===n?'active':''}" data-action="font-set" data-value="${n}">${label}</button>`).join('')}</div><p style="font-size:${S.settings.font}px">先看懂判断依据，再通过自测检验。</p>`),'font-set':el=>{S.settings.font=+el.dataset.value;save();close();render();},
 'install':()=>sheet('像App一样打开',`<h3>iPhone</h3><p>在Safari打开网址，选择“分享 → 添加到主屏幕”。</p><h3>Android</h3><p>从浏览器菜单选择“安装应用”或“添加到主屏幕”。</p><h3>离线使用</h3><p>首次联网完整打开后可准备离线缓存，也可使用交付的独立HTML。文件预览器可能不运行脚本，请用浏览器打开。</p><div class="callout mt16">${icon('device')}<span>离线、在线、不同浏览器的本机存储各自独立。需要交换进度时点手动云同步，或导出、恢复备份。</span></div>`),
 'reset-prompt':()=>sheet('清除本机学习记录？',`<p>将清除本机的已看、答题、全部自测轮次、错题、收藏和笔记。内置与自定义题库保留；云端数据不受影响。请先导出备份。</p><div class="sheet-footer">${button('导出备份','export-backup','','outline')}${button('清除本机记录','reset','','danger')}</div>`),
 'reset':()=>{const custom=M.clone(S.customBanks),b=S.bank,cfg=M.clone(S.sync),settings=M.clone(S.settings);S=M.fresh();S.customBanks=custom;S.bank=b;S.settings=settings;S.sync={...cfg,lastSyncedAt:0,lastSuccessAt:0};saveBlocked=false;try{localStorage.removeItem(M.OLD_KEY);}catch{}rebuild();save();close();go('me');toast('本机学习记录已清除，云端记录保留。');}
};
function render(){document.documentElement.style.setProperty('--textsize',S.settings.font+'px');const content=view.page==='home'?home():view.page==='groups'?library():view.page==='tests'?tests():view.page==='review'?review():view.page==='me'?me():view.page==='quiz'?quiz():result();$('#app').innerHTML=['quiz','result'].includes(view.page)?content:top()+`<main id="main" class="container main v2-main ${view.page==='home'?'v2-home':''}">${content}</main>`+nav();storedWarning();}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;try{actions[el.dataset.action]?.(el);}catch(error){toast(error.message||'操作暂未完成，进度保留。');}});
document.addEventListener('input',e=>{if(e.target.id==='search'){view.search=e.target.value;view.limit=40;$('#question-results').innerHTML=searchResults();}});
document.addEventListener('change',e=>{if(e.target.id==='round-picker'){S.currentRounds[S.bank]={id:e.target.value,at:Date.now()};S.updatedAt=Date.now();save();render();}});
$('#bank-file').addEventListener('change',e=>{if(e.target.files[0])prepareBank(e.target.files[0]);});$('#backup-file').addEventListener('change',e=>{if(e.target.files[0])prepareBackup(e.target.files[0]);});
$('#sheet').addEventListener('cancel',()=>{if(syncController)syncController.abort();});
$('#sheet').addEventListener('click',e=>{if(e.target===$('#sheet')){const r=$('#sheet').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
document.addEventListener('keydown',e=>{if(view.page!=='quiz'||$('#sheet').open||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(/^[1-6]$/.test(e.key)){const b=document.querySelectorAll('.choice')[+e.key-1];if(b&&!b.disabled){e.preventDefault();b.click();}}if(e.key==='Enter'){const b=$('.quiz-footer .primary');if(b&&!b.disabled){e.preventDefault();b.click();}}});
window.addEventListener('beforeunload',save);document.addEventListener('visibilitychange',()=>{if(document.hidden)save();});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(['home','groups','tests','review','me'].includes(p)){view.page=p;render();}});
const initial=location.hash.slice(1);if(['home','groups','tests','review','me'].includes(initial))view.page=initial;
save();render();
if(location.protocol!=='file:'&&'serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
window.StudyApp={version:5,appVersion:'2.0.0',bank:()=>S.bank,questionCount:()=>qmap.size,summary:()=>M.bankStats(S,bank()),state:()=>M.snapshot(S)};
})();
